var n=`1008-khao-man-gai`;var t=`world-1008`;var a=`TH`;var o=`southeast-asia`;var s=4;var r=71;var c={en:`Khao Man Gai`,ua:`Кхао ман гай`};var l={en:`Khao Man Gai is a dish from Thailand prepared with whole chicken, green onion, jasmine rice, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кхао ман гай, страва кухні країни Таїланд, яку готують із таких продуктів: ціла курка, зелена цибуля, рис жасмин, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Poach the whole chicken gently with ginger and scallions until the thickest part reaches 74°C; remove it from the broth, rest and cut into portions.`,ua:`Обережно варіть цілу курку з імбиром і зеленою цибулею, доки найтовща частина не досягне 74°C; вийміть із бульйону, дайте відпочити й наріжте.`,t:[`simmering`,`skimming-foam`],m:40,i:[[`whole-chicken`,1200,`g`],[`water`,1850,`ml`],[`ground-ginger`,60,`g`],[`green-onion`,75,`g`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 22 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 22 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`jasmine-rice`,420,`g`],[`chicken-stock`,650,`ml`],[`garlic`,3,`clove`],[`chicken-schmaltz`,35,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`ground-ginger`,20,`g`],[`serrano-pepper`,2,`pcs`],[`light-soy-sauce`,35,`ml`],[`lime-juice`,30,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`cucumber`,200,`g`],[`cilantro`,20,`g`]]}];var g={slug:n,id:t,country:`TH`,region:o,servings:4,minutes:71,title:c,text:l,steps:h};export{a as country,g as default,t as id,r as minutes,o as region,s as servings,n as slug,h as steps,l as text,c as title};